{
  "material_version": "pilot-v10",
  "claims": [
    {
      "claim_id": "AV01",
      "claim": "在小圆物件沉入水中的那组镜头里，清晰的无词女声哼唱从头到尾都是主要人声。"
    },
    {
      "claim_id": "AV02",
      "claim": "链饰询问附近那段清楚可辨的无词女声哼唱，在画面切成女子正面特写之前就已经结束。"
    },
    {
      "claim_id": "AV03",
      "claim": "室内男子通过电话讲述梦境的男声，在画面依次转为草叶、树林中相对的男女、海边人物时仍作为同一段叙述延续；这些户外镜头并没有变成画面人物的现场对白。"
    },
    {
      "claim_id": "AV04",
      "claim": "厨房对话中，男声问对方是否介意使用那个标志时，画面仍对着这名男子、能看到他的嘴，而不是女子的正面特写。"
    }
  ]
}
